def migrate(cr, version):
    """Adopt service categories/products that already exist without an XML id.

    Part of this hierarchy was built by hand before this data file existed.
    Registering those records under the ids the data file uses means the
    noupdate records match them instead of creating duplicates, and lets new
    children reference existing parents.
    """
    env = api.Environment(cr, SUPERUSER_ID, {})
    Category = env['product.category']
    Template = env['product.template']
    Data = env['ir.model.data']
    for xmlid, model, name, path in ENTRIES:
        if Data.search_count([('module', '=', 'crm_deals'), ('name', '=', xmlid)]):
            continue
        parent = False
        resolved = True
        for step in path:
            found = Category.search(
                [('name', '=', step), ('parent_id', '=', parent)], limit=1)
            if not found:
                resolved = False
                break
            parent = found.id
        if not resolved:
            continue
        if model == 'product.category':
            record = Category.search(
                [('name', '=', name), ('parent_id', '=', parent)], limit=1)
        else:
            record = Template.search(
                [('name', '=', name), ('categ_id', '=', parent)], limit=1)
        if record:
            Data.create({
                'module': 'crm_deals', 'name': xmlid, 'model': model,
                'res_id': record.id, 'noupdate': True,
            })
